    (177, 'chilan-berry', '카리열매', 'type-protection', 10, '포켓몬에게 지니게 하면 노말 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a Normal-type attack to halve the damage.', true, false),
    (190, 'bright-powder', '반짝가루', 'held-items', 10, '반짝반짝 빛나는 가루. 지니게 하면 빛이 상대를 혼란시켜 기술이 명중되기 어려워진다.', 'Held: Increases the holder’s evasion by 1/9 (11 1/9%).', true, false),
    (191, 'white-herb', '하양허브', 'held-items', 10, '지니게 한 포켓몬의 능력이 떨어졌을 때 한 번만 원래 상태로 돌아온다.', 'Held: Resets all lowered stats to normal at end of turn. Consumed after use.', true, false),
    (194, 'quick-claw', '선제공격손톱', 'held-items', 80, '가볍고 날카로운 손톱. 지니게 하면 상대보다 먼저 행동할 수도 있다.', 'Held: Holder has a 3/16 (18.75%) chance to move first.', true, false),
    (196, 'mental-herb', '멘탈허브', 'held-items', 10, '지니게 한 포켓몬은 헤롱헤롱 상태가 되었을 때 한 번만 회복한다.', 'Held: Consumed to cure infatuation. Gen V: Also removes Taunt, Encore, Torment, Disable, and Cursed Body.', true, false),
    (197, 'choice-band', '구애머리띠', 'choice', 10, '기술을 구애받는 머리띠. 지니게 하면 공격은 올라가지만 똑같은 기술밖에 쓰지 못한다.', 'Held: Increases Attack by 50%, but restricts the holder to only one move.', true, false),
    (198, 'kings-rock', '왕의징표석', 'held-items', 30, '지니게 하면 공격해서 데미지를 줄 때 상대를 풀죽이기도 한다.', 'Held: Damaging moves gain a 10% chance to make their target flinch. Traded on a Poliwhirl: Holder evolves into Politoed. Traded on a Slowpoke: Holder evolves into Slowking.', true, false),
    (199, 'silver-powder', '은빛가루', 'type-enhancement', 10, '은색으로 반짝이는 가루. 지니게 하면 벌레타입 기술의 위력이 올라간다.', 'Held: Bug-Type moves from holder do 20% more damage.', true, false),
    (207, 'focus-band', '기합의머리띠', 'held-items', 10, '지니게 하면 기절할 듯한 기술을 받아도 HP를 1 남겨서 견디기도 한다.', 'Held: Holder has 10% chance to survive attacks or self-inflicted damage at 1 HP.', true, false),
    (209, 'scope-lens', '초점렌즈', 'held-items', 30, '약점이 보이는 렌즈. 지니게 한 포켓몬의 기술이 급소에 맞기 쉬워진다.', 'Held: Raises the holder’s critical hit ratio by one stage.', true, false),
    (210, 'metal-coat', '금속코트', 'type-enhancement', 30, '특수한 금속 장막. 지니게 하면 강철타입 기술의 위력이 올라간다.', 'Held: Steel-Type moves from holder do 20% more damage.', true, false),
    (211, 'leftovers', '먹다남은음식', 'held-items', 10, '지니게 하면 포켓몬의 HP가 배틀을 하는 동안 조금씩 회복된다.', 'Held: Restores 1/16 (6.25%) holder’s max HP at the end of each turn.', true, false),
    (213, 'light-ball', '전기구슬', 'species-specific', 30, '피카츄에게 지니게 하면 공격과 특수공격의 위력이 올라가는 이상한 구슬.', 'Doubles Pikachu’s Attack and Special Attack. Breed on Pikachu or Raichu: Pichu Egg will have Volt Tackle.', true, false),
    (214, 'soft-sand', '부드러운모래', 'type-enhancement', 10, '만지면 보슬보슬한 모래. 지니게 하면 땅타입 기술의 위력이 올라간다.', 'Held: Ground-Type moves from holder do 20% more damage.', true, false),
    (215, 'hard-stone', '딱딱한돌', 'type-enhancement', 100, '절대 깨지지 않는 돌. 지니게 하면 바위타입 기술의 위력이 올라간다.', 'Held: Rock-Type moves from holder do 20% more damage.', true, false),
    (216, 'miracle-seed', '기적의씨', 'type-enhancement', 30, '생명이 깃든 씨앗. 지니게 하면 풀타입 기술의 위력이 올라간다.', 'Held: Grass-Type moves from holder do 20% more damage.', true, false),
    (217, 'black-glasses', '검은안경', 'type-enhancement', 30, '괴상하게 보이는 안경. 지니게 하면 악타입 기술의 위력이 올라간다.', 'Held: Dark-Type moves from holder do 20% more damage.', true, false),
    (218, 'black-belt', '검은띠', 'type-enhancement', 30, '마음을 긴장시키는 띠. 지니게 하면 격투타입 기술의 위력이 올라간다.', 'Held: Fighting-Type moves from holder do 20% more damage.', true, false),
    (219, 'magnet', '자석', 'type-enhancement', 30, '강력한 자석. 지니게 하면 전기타입 기술의 위력이 올라간다.', 'Held: Electric-Type moves from holder do 20% more damage.', true, false),
    (220, 'mystic-water', '신비의물방울', 'type-enhancement', 30, '물방울 모양의 보석. 지니게 하면 물타입 기술의 위력이 올라간다.', 'Held: Water-Type moves from holder do 20% more damage.', true, false),
    (221, 'sharp-beak', '예리한부리', 'type-enhancement', 50, '길고 뾰족한 부리. 지니게 하면 비행타입 기술의 위력이 올라간다.', 'Held: Flying-Type moves from holder do 20% more damage.', true, false),
    (222, 'poison-barb', '독바늘', 'type-enhancement', 70, '독이 있는 작은 침. 지니게 하면 독타입 기술의 위력이 올라간다.', 'Held: Poison-Type moves from holder do 20% more damage.', true, false),
    (223, 'never-melt-ice', '녹지않는얼음', 'type-enhancement', 30, '열을 가까이하지 않게 하는 얼음. 지니게 하면 얼음타입 기술의 위력이 올라간다.', 'Held: Ice-Type moves from holder do 20% more damage.', true, false),
    (224, 'spell-tag', '저주의부적', 'type-enhancement', 30, '괴상하고 으스스한 부적. 지니게 하면 고스트타입 기술의 위력이 올라간다.', 'Held: Ghost-Type moves from holder do 20% more damage.', true, false),
    (225, 'twisted-spoon', '휘어진스푼', 'type-enhancement', 30, '염동력을 담은 숟가락. 지니게 하면 에스퍼타입 기술의 위력이 올라간다.', 'Held: Psychic-Type moves from holder do 20% more damage.', true, false),
    (226, 'charcoal', '목탄', 'type-enhancement', 30, '물건을 태우는 연료. 지니게 하면 불꽃타입 기술의 위력이 올라간다.', 'Held: Fire-Type moves from holder do 20% more damage.', true, false),
    (227, 'dragon-fang', '용의이빨', 'type-enhancement', 70, '단단하고 날카로운 이빨. 지니게 하면 드래곤타입 기술의 위력이 올라간다.', 'Held: Dragon-Type moves from holder do 20% more damage.', true, false),
    (228, 'silk-scarf', '실크스카프', 'type-enhancement', 10, '감촉이 좋은 스카프. 지니게 하면 노말타입 기술의 위력이 올라간다.', 'Held: Normal-Type moves from holder do 20% more damage.', true, false),
    (230, 'shell-bell', '조개껍질방울', 'held-items', 30, '지니게 한 포켓몬이 공격하여 상대에게 데미지를 줬을 때 HP를 조금 회복할 수 있다.', 'Held: Holder receives 1/8 of the damage it deals when attacking.', true, false),
    (242, 'wide-lens', '광각렌즈', 'held-items', 10, '물건이 크게 보이는 렌즈. 지니게 하면 기술의 명중률이 조금 올라간다.', 'Held: Provides a 1/10 (10%) boost in accuracy to the holder.', true, false),
    (243, 'muscle-band', '힘의머리띠', 'held-items', 10, '힘이 끓어오르는 머리띠. 지니게 하면 물리 기술의 위력이 조금 올라간다.', 'Held: Boosts the damage of physical moves used by the holder by 10%.', true, false),
    (244, 'wise-glasses', '박식안경', 'held-items', 10, '두꺼운 렌즈를 붙인 안경. 지니게 하면 특수 기술의 위력이 조금 올라간다.', 'Held: Boosts the damage of special moves used by the holder by 1/10 (10%).', true, false),
    (245, 'expert-belt', '달인의띠', 'held-items', 10, '오래 사용한 까만 띠. 지니게 하면 효과가 뛰어날 때 기술의 위력이 조금 올라간다.', 'Held: Holder’s Super Effective moves do 20% extra damage.', true, false),
    (246, 'light-clay', '빛의점토', 'held-items', 30, '지니게 한 포켓몬이 빛의장막이나 리플렉터를 사용했을 때 여느 때보다 긴 시간 동안 지속된다.', 'Held: Light Screen and Reflect used by the holder last 8 rounds instead of 5.', true, false),
    (247, 'life-orb', '생명의구슬', 'held-items', 30, '지니게 하면 공격할 때마다 HP가 조금씩 줄지만 기술의 위력이 올라간다.', 'Held: Holder’s moves inflict 30% extra damage, but cost 10% max HP.', true, false),
    (248, 'power-herb', '파워풀허브', 'held-items', 10, '지니게 한 포켓몬은 한 번만 1턴째에 힘을 모으는 기술을 바로 사용할 수가 있다.', 'Held: Both turns of a two-turn charge move happen at once. Consumed upon use.', true, false),
    (252, 'focus-sash', '기합의띠', 'held-items', 10, '지니게 하면 HP가 꽉 찼을 때 기절할 듯한 기술을 당해도 HP 1로 한 번은 버틴다.', 'Held: Holder survives any single-hit attack at 1 HP if at max HP, then the item is consumed.', true, false),
    (253, 'zoom-lens', '포커스렌즈', 'held-items', 10, '지니게 한 포켓몬이 상대보다도 행동하는 것이 늦을 때 기술이 명중하기 쉬워진다.', 'Held: Provides a 1/5 (20%) boost in accuracy if the holder moves after the target.', true, false),
    (254, 'metronome', '메트로놈', 'held-items', 30, '지니게 하면 똑같은 기술을 연속으로 사용했을 때 위력이 올라간다. 그만두면 위력이 되돌아간다.', 'Held: Consectutive uses of the same attack have a cumulative damage boost of 10%. Maximum 100% boost.', true, false),
    (255, 'iron-ball', '검은철구', 'bad-held-items', 130, '지니게 하면 스피드가 떨어진다. 비행타입이나 부유포켓몬은 땅 기술에 맞아 버린다.', 'Held: Holder’s Speed is halved. Negates all Ground-type immunities, and makes Flying-types take neutral damage from Ground-type moves. Arena Trap. Spikes, and Toxic Spikes affect the holder.', true, false),
    (259, 'icy-rock', '차가운바위', 'held-items', 40, '지니게 한 포켓몬이 싸라기눈을 쓰면 여느 때보다 싸라기눈의 시간이 길어진다.', 'Held: Hail by the holder lasts 8 rounds instead of 5.', true, false),
    (260, 'smooth-rock', '보송보송바위', 'held-items', 10, '지니게 한 포켓몬이 모래바람을 쓰면 여느 때보다 모래바람의 시간이 길어진다.', 'Held: Sandstorm by the holder lasts 8 rounds instead of 5.', true, false),
    (261, 'heat-rock', '뜨거운바위', 'held-items', 60, '지니게 한 포켓몬이 쾌청을 쓰면 여느 때보다 쾌청의 시간이 길어진다.', 'Held: Sunny Day by the holder lasts 8 rounds instead of 5.', true, false),
    (262, 'damp-rock', '축축한바위', 'held-items', 60, '지니게 한 포켓몬이 비바라기를 쓰면 여느 때보다 비 내리는 시간이 길어진다.', 'Held: Rain Dance by the holder lasts 8 rounds instead of 5.', true, false),
